name: CI
on:
  pull_request:
  push:
    branches: [main]
  # Dispatchable so baselining can start this run on the nightly maintenance PR.
  # That PR's branch push and its open both ride the Action's GITHUB_TOKEN, and
  # GitHub's recursion guard suppresses workflow runs for events that token
  # authors — so the PR gets no pull_request run at all, and `maintenance.delivery:
  # auto-merge` waits on a check that never appears. workflow_dispatch is the
  # guard's one documented exception, which is why baselining's deliver() starts
  # the checks itself.
  workflow_dispatch:
jobs:
  conformance:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v5
      - uses: actions/setup-node@v5
        with:
          node-version: 22
      - name: Claudinite world-scope conformance sweep
        run: node .claudinite/shared/engine/checks/check_the_world.mjs
      # The glob is explicit on purpose: bare `node --test` skips dot-directories,
      # so it would find none of these and still exit green (claudinite-website/node-test-discovery).
      - name: Local pack rule fixtures
        run: node --test '.claudinite/local/packs/**/*.test.mjs'
====
#!/usr/bin/env node
//
// Bump the site version for a production release.
//
// Scheme: 1.<mmdd>.<previous patch + 1>
//   - major  stays 1
//   - minor  is the release date as zero-padded month+day (Asia/Jerusalem, the
//            timezone the rest of the fleet stamps its builds in)
//   - patch  is a monotonic counter: previous patch + 1, so it always advances
//            even when the day (and therefore the minor) rolls over
//
// package.json is the single source of truth for the version. The deploy
// workflow runs this, then commits the bumped files back to main — so the number
// in the repo always names the last release that actually went out.
//
// This script also owns the site's copy of the version: the footer's `title`
// tooltip on every page carrying the copyright element. That copy is generated
// here, never hand-edited, and the
