// Parameterised screenshot driver: node shoot.mjs <url> <width> <out.png> [reducedMotion] [clipHeight]
import { chromium } from 'playwright-core';
const [url, w, out, rm, clipH] = process.argv.slice(2);
const b = await chromium.launch({ executablePath: '/opt/pw-browsers/chromium-1194/chrome-linux/chrome', args: ['--no-sandbox'] });
const p = await b.newPage({ viewport: { width: Number(w), height: 900 }, deviceScaleFactor: 1, reducedMotion: rm === 'reduce' ? 'reduce' : 'no-preference' });
const errors = [];
p.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
p.on('pageerror', (e) => errors.push(String(e)));
await p.goto(url, { waitUntil: 'networkidle' });
await p.evaluate(async () => { for (let y = 0; y < document.body.scrollHeight; y += 600) { window.scrollTo(0, y); await new Promise(r => setTimeout(r, 60)); } window.scrollTo(0, 0); });
await p.waitForTimeout(rm === 'reduce' ? 500 : 6000);
const overflow = await p.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth);
const height = await p.evaluate(() => document.body.scrollHeight);
if (clipH) await p.screenshot({ path: out, clip: { x: 0, y: 0, width: Number(w), height: Number(clipH) } });
else await p.screenshot({ path: out, fullPage: true });
console.log(JSON.stringify({ out, height, overflowPx: overflow, errors }));
await b.close();

