492	/* ======================= the desk scene =======================
493	   The hero narrative: one operator's desk over eight beats. Everything is
494	   driven by cumulative beat classes (.b1 … .b8) that assets/main.js adds to
495	   the svg, so each visual state is a plain rule keyed off a beat rather than
496	   one long keyframe timeline. Motion signature is load-bearing: the agent
497	   eases (organic, and it decays), the robot steps (deterministic, and it
498	   does not). */
499	.scene { margin: clamp(18px, 2.5vw, 30px) auto 0; max-width: 1040px; }
500	.scene svg { width: 100%; height: auto; display: block; }
501	.scene-caption { display: flex; align-items: center; justify-content: center; gap: 14px; flex-wrap: wrap; margin-top: 10px; }
502	
503	/* The claim the whole scene stands in front of. */
504	.sc-curve {
505	  fill: none; stroke: var(--accent); stroke-width: 2.5; opacity: 0.16;
506	  stroke-linecap: round; stroke-dasharray: 1; stroke-dashoffset: 1;
507	  transition: stroke-dashoffset 2.4s linear;
508	}
509	.b1 .sc-curve { stroke-dashoffset: 0.86; }
510	.b2 .sc-curve { stroke-dashoffset: 0.72; }
511	.b3 .sc-curve { stroke-dashoffset: 0.6; }
512	.b4 .sc-curve { stroke-dashoffset: 0.47; }
513	.b5 .sc-curve { stroke-dashoffset: 0.35; }
514	.b6 .sc-curve { stroke-dashoffset: 0.22; }
515	.b7 .sc-curve { stroke-dashoffset: 0.11; }
516	.b8 .sc-curve { stroke-dashoffset: 0; }
517	
518	/* Anything marked .fN is staged, and enters when its beat arrives. */
519	.b1 .f1, .b2 .f2, .b3 .f3, .b4 .f4,
520	.b5 .f5, .b6 .f6, .b7 .f7, .b8 .f8 { opacity: 1; transform: scale(1); }
521	
522	.sc-work { opacity: 0.55; }
523	.sc-ground { stroke: var(--line); stroke-width: 1.5; fill: none; }
524	.sc-desk { stroke: var(--ink); stroke-width: 2.5; fill: none; stroke-linecap: round; }
525	.sc-keys { fill: var(--paper-2); stroke: var(--ink); stroke-width: 2; }
526	
527	/* --- screens: each slot is fixed, so one arriving never moves the others --- */
528	.sc-screen { opacity: 0; transform: scale(0.92); transform-box: fill-box; transform-origin: center;
529	  transition: opacity 0.35s ease-out, transform 0.35s ease-out; }
530	.sc-glass { fill: var(--paper); stroke: var(--ink); stroke-width: 2; }
531	.sc-bar { stroke: var(--line); stroke-width: 1.5; fill: none; }
532	.sc-stand, .sc-arm { stroke: var(--ink-soft); stroke-width: 2; fill: none; }
533	.sc-code {
534	  stroke: var(--ink-soft); stroke-width: 3; fill: none; stroke-linecap: round; opacity: 0;
535	  animation: sc-type 3.6s linear infinite; animation-delay: calc(var(--n) * 0.72s);
536	}
537	.sc-code-good { stroke: var(--accent); }
538	@keyframes sc-type { 0%, 4% { opacity: 0; } 10%, 82% { opacity: 0.55; } 92%, 100% { opacity: 0; } }
539	/* Faster work once the agent is grown, faster still once the robot is on it. */
540	.b2 .sc-code { animation-duration: 1.8s; animation-delay: calc(var(--n) * 0.36s); }
541	.b5 .sc-code { animation-duration: 1.4s; animation-delay: calc(var(--n) * 0.28s); }
542	
543	.sc-tech { fill: none; stroke: var(--ink); stroke-width: 2; transition: stroke 0.4s ease, fill 0.4s ease; }
544	.sc-tech-dot { fill: var(--ink); transition: fill 0.4s ease; }
545	.sc-known .sc-tech { stroke: var(--accent-deep); fill: var(--accent-wash); }
546	.sc-known .sc-tech-dot { fill: var(--accent-deep); }
547	
548	/* --- bugs: what a crusty corpus starts writing into the work --- */
549	.sc-bug { opacity: 0; transform: scale(0.5); transform-box: fill-box; transform-origin: center;
550	  transition: opacity 0.15s ease-out, transform 0.15s ease-out; }
551	.sc-x { stroke: var(--red); stroke-width: 3; fill: none; stroke-linecap: round; }
552	.sc-zig { stroke: var(--red); stroke-width: 3; fill: none; stroke-linecap: round; stroke-linejoin: round; }
553	.b4 .sc-bug { opacity: 1; transform: scale(1); }
554	.b6 .sc-bug { opacity: 0; transform: scale(1); }
555	.sc-tick { stroke: var(--accent); stroke-width: 3; fill: none; stroke-linecap: round;
556	  stroke-linejoin: round; opacity: 0; transition: opacity 0.3s ease; }
557	.b6 #sc-s1 .sc-tick { opacity: 1; }
558	.b7 #sc-s1 .sc-tick { opacity: 0; }
559	
560	/* --- work lines: dashes running from whoever is serving a screen --- */
561	.sc-wl { fill: none; stroke-width: 1.5; stroke-linecap: round; opacity: 0; transition: opacity 0.4s ease; }
562	.sc-wl-a { stroke: var(--accent); stroke-dasharray: 4 10; animation: sc-flow 2s linear infinite; }
563	.sc-wl-r { stroke: var(--accent); stroke-dasharray: 6 6; animation: sc-flow 1.2s steps(6) infinite; }
564	@keyframes sc-flow { to { stroke-dashoffset: -28; } }
565	.b2 .sc-wl-a { animation-duration: 1s; }
566	/* Stuttering output while the agent is crusted over. */
567	.b3 .sc-wl-a { stroke-dasharray: 2 14; animation-timing-function: steps(6); }
568	.b6 .sc-wl-a { stroke-dasharray: 4 10; animation-timing-function: linear; }
569	
570	/* --- the agents: our crystal, grown and then relieved --- */
571	.sc-agent { transform-box: fill-box; transform-origin: bottom center;
572	  transition: transform 0.6s ease; }
573	.sc-cryst { transition: fill 0.8s ease; }
574	.sc-facet { transition: opacity 0.8s ease; }
575	#sc-agent-a { transform: scale(1); }
576	.b2 #sc-agent-a { transform: scale(1.4); }
577	.b3 #sc-agent-a { transform: scale(1.8); }
578	.b6 #sc-agent-a { transform: scale(0.9); }
579	#sc-agent-b { opacity: 0; transform: scale(0.7); transition: opacity 0.5s ease, transform 0.6s ease; }
580	.b2 #sc-agent-b { opacity: 1; transform: scale(1); }
581	.b6 #sc-agent-b { transform: scale(0.8); }
582	
583	/* Cruft accretes as bad little copies of itself, plus staleness. */
584	.sc-crust { opacity: 0; transition: opacity 0.5s ease; }
585	.b3 .sc-crust { opacity: 1; }
586	.b6 .sc-crust { opacity: 0; }
587	.sc-barn { fill: none; stroke: var(--ink-soft); stroke-width: 1.2; transform-box: fill-box;
588	  transform-origin: center; transform: scale(0); transition: transform 0.15s ease-out;
589	  transition-delay: calc(var(--n) * 0.12s); }
590	.b3 .sc-barn { transform: scale(1); }
591	.b6 .sc-barn { transform: scale(0); transition-delay: calc(var(--n) * 0.06s); }
592	.sc-moss { fill: var(--amber-wash); stroke: var(--amber); stroke-width: 1.2; }
593	.sc-moss-2 { opacity: 0; transition: opacity 0.4s ease; }
594	.b4 .sc-moss-2 { opacity: 1; }
595	.sc-drip { stroke: var(--amber); stroke-width: 1.5; fill: none; stroke-linecap: round; }
596	.b3 .sc-cryst { fill: var(--amber-wash); }
597	.b3 .sc-facet { opacity: 0.25; }
598	.b6 .sc-cryst { fill: var(--accent-wash); }
599	.b6 .sc-facet { opacity: 0.6; }
600	
601	/* Jolts: never more than one per agent at a time, co-prime periods. */
602	.sc-jolt { fill: none; stroke: var(--amber); stroke-width: 2; stroke-linecap: round; opacity: 0; }
603	.b4 .sc-jolt-1 { animation: sc-spark 0.9s steps(1) infinite; }
604	.b4 .sc-jolt-2 { animation: sc-spark 1.3s steps(1) infinite; }
605	.b4 .sc-jolt-3 { animation: sc-spark 1.1s steps(1) infinite; }
606	.b6 .sc-jolt { animation: none !important; opacity: 0; }
607	@keyframes sc-spark { 0%, 12% { opacity: 1; } 13%, 100% { opacity: 0; } }
608	
609	/* --- the robot: everything the crystal is not. Straight, ruled, stepped. --- */
610	.sc-robot {
611	  opacity: 0; transform: translateX(40px) scale(0.55);
612	  transform-box: fill-box; transform-origin: bottom center;
613	  transition: opacity 0.3s steps(4), transform 0.9s steps(8);
614	}
