1	/* claudinite.com — behavior. Vanilla JS, no dependencies.
2	   Five jobs: reveal-on-scroll, the hero desk scene, the compounding chart,
3	   the mechanism animations (session terminal, baselining board, adopt
4	   typewriter), and rendering the promoted-content slots from data/promoted.js.
5	   All motion is skipped under prefers-reduced-motion. */
6	(function () {
7	  'use strict';
8	
9	  var REDUCED = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
10	  var DATA = window.CLAUDINITE || null;
11	  var SVG_NS = 'http://www.w3.org/2000/svg';
12	
13	  function el(tag, cls, text) {
14	    var n = document.createElement(tag);
15	    if (cls) n.className = cls;
16	    if (text !== undefined) n.textContent = text;
17	    return n;
18	  }
19	
20	  /* ---------------------- reveal on scroll ---------------------- */
21	  var revealed = document.querySelectorAll('.reveal');
22	  if (REDUCED || !('IntersectionObserver' in window)) {
23	    revealed.forEach(function (n) { n.classList.add('in'); });
24	  } else {
25	    var ro = new IntersectionObserver(function (entries) {
26	      entries.forEach(function (e) {
27	        if (e.isIntersecting) { e.target.classList.add('in'); ro.unobserve(e.target); }
28	      });
29	    }, { threshold: 0.18 });
30	    revealed.forEach(function (n) { ro.observe(n); });
31	  }
32	
33	  /* ------------------ hero: the desk scene ----------------------
34	     Eight beats of one operator's desk. The scheduler only adds cumulative
35	     classes b1..b8 to the svg; every visual state is a CSS rule keyed off a
36	     beat, which keeps eight beats editable and makes the loop reset a matter
37	     of dropping the classes. Beat 4 stacks three novelties, so its screen,
38	     bugs and jolts are staggered as sub-cues rather than landing together. */
39	  (function deskScene() {
40	    var svg = document.getElementById('scene-viz');
41	    if (!svg) return;
42	
43	    var BEATS = [2500, 2000, 2500, 3000, 2000, 3000, 2500, 2500];
44	    var HOLD = 1200;
45	    var known = ['sc-s5', 'sc-s6'];   // screens whose technology gets learned
46	    var timers = [];
47	
48	    function clear() {
49	      timers.forEach(clearTimeout); timers = [];
50	      for (var i = 1; i <= 8; i++) svg.classList.remove('b' + i);
51	      known.forEach(function (id) {
52	        var n = document.getElementById(id);
53	        if (n) n.classList.remove('sc-known');
54	      });
55	    }
56	
57	    function at(ms, fn) { timers.push(setTimeout(fn, ms)); }
58	
59	    if (REDUCED) {
60	      // A still frame cannot tell an arc, so it states the destination: six
61	      // clean screens, small tidy agents, the assistant grown, nobody typing.
62	      for (var b = 1; b <= 8; b++) svg.classList.add('b' + b);
63	      known.forEach(function (id) {
64	        var n = document.getElementById(id);
65	        if (n) n.classList.add('sc-known');
66	      });
67	      return;
68	    }
69	
70	    function play() {
71	      clear();
72	      var t = 0;
73	      BEATS.forEach(function (dur, i) {
74	        at(t, function () { svg.classList.add('b' + (i + 1)); });
75	        t += dur;
76	      });
77	      // The technology on a screen is only known once the pack has landed.
78	      at(BEATS.slice(0, 6).reduce(function (a, b) { return a + b; }, 0) + 1400, function () {
79	        var n = document.getElementById('sc-s5');
80	        if (n) n.classList.add('sc-known');
81	      });
82	      at(BEATS.slice(0, 7).reduce(function (a, b) { return a + b; }, 0) + 500, function () {
83	        var n = document.getElementById('sc-s6');
84	        if (n) n.classList.add('sc-known');
85	      });
86	      at(t + HOLD, play);
87	    }
88	
89	    var replay = document.getElementById('sc-replay');
90	    if (replay) replay.addEventListener('click', play);
91	
92	    if (!('IntersectionObserver' in window)) { play(); return; }
93	    var seen = false;
94	    var io = new IntersectionObserver(function (entries) {
95	      entries.forEach(function (e) {
96	        if (e.isIntersecting && !seen) { seen = true; play(); io.disconnect(); }
97	      });
98	    }, { threshold: 0.25 });
99	    io.observe(svg);
100	  })();
101	
102	  /* ---------------- the compounding chart ----------------------
103	     The curves and the meters' end states are authored in the markup, so the
104	     page states its argument with scripting off. This only animates the way
105	     in: a left-to-right sweep over the curves, the meters filling beneath it,
106	     and the prose-only meter pinning at full exactly where its curve flattens.
107	     Geometry constants mirror the SVG's own coordinates. */
108	  (function compoundChart() {
109	    var svg = document.getElementById('compound-viz');
110	    if (!svg) return;
111	    var clip = document.getElementById('cx-clip-rect');
112	    var fillProse = document.getElementById('cx-fill-prose');
113	    var fillClaud = document.getElementById('cx-fill-claud');
114	    var pin = document.getElementById('cx-pin');
115	    var replay = document.getElementById('cx-replay');
116	
117	    var SWEEP = 554, METER = 426;
118	    var PIN_T = 0.55;             // prose fills the budget here, and stops climbing
119	    var LATE_T = 0.72;            // the curves are far enough along to be named
120	    var PROMOS = [0.30, 0.50, 0.66, 0.79, 0.90];  // promotions, arriving faster
121	    var FREED = 0.30;             // budget each promotion hands back
122	    var FLOOR = 0.10;
123	    var DUR = 7200, HOLD = 2800;
124	
125	    function proseFill(t) { return Math.min(1, t / PIN_T); }
126	    function claudFill(t) {
127	      var freed = 0;
128	      for (var i = 0; i < PROMOS.length; i++) if (t >= PROMOS[i]) freed += FREED;
129	      return Math.max(FLOOR, Math.min(1, t / PIN_T - freed));
130	    }
131	
132	    function draw(t) {
133	      clip.setAttribute('width', SWEEP * t);
134	      fillProse.setAttribute('width', METER * proseFill(t));
135	      fillClaud.setAttribute('width', METER * claudFill(t));
136	      svg.classList.toggle('cx-pinned', t >= PIN_T);
137	      svg.classList.toggle('cx-late', t >= LATE_T);
138	    }
139	
140	    // With motion suppressed the authored end state is already correct.
141	    if (REDUCED) { svg.classList.add('cx-pinned'); svg.classList.add('cx-late'); return; }
142	
143	    var raf = null, timer = null, promoIdx = 0;
144	
145	    function flash() {
146	      fillClaud.classList.remove('cx-freed');
147	      void fillClaud.getBoundingClientRect();   // restart the animation
148	      fillClaud.classList.add('cx-freed');
149	    }
150	
151	    function play() {
152	      if (raf) cancelAnimationFrame(raf);
153	      if (timer) clearTimeout(timer);
154	      promoIdx = 0;
155	      var start = null;
156	      svg.classList.add('cx-running');
157	      (function step(now) {
158	        if (start === null) start = now;
159	        var t = Math.min(1, (now - start) / DUR);
160	        draw(t);
161	        while (promoIdx < PROMOS.length && t >= PROMOS[promoIdx]) { flash(); promoIdx++; }
162	        if (t < 1) raf = requestAnimationFrame(step);
163	        else { svg.classList.remove('cx-running'); timer = setTimeout(play, HOLD); }
164	      })(performance.now());
165	    }
166	
167	    if (replay) replay.addEventListener('click', play);
168	
169	    draw(0);
170	    if (!('IntersectionObserver' in window)) { play(); return; }
171	    var seen = false;
172	    var io = new IntersectionObserver(function (entries) {
173	      entries.forEach(function (e) {
174	        if (e.isIntersecting && !seen) { seen = true; play(); io.disconnect(); }
175	      });
176	    }, { threshold: 0.3 });
177	    io.observe(svg);
178	  })();
179	
180	  /* ------------------ session-loop terminal ---------------------- */
181	  (function sessionTerm() {
182	    var body = document.getElementById('term-body');
183	    if (!body) return;
184	    var lines = Array.prototype.slice.call(body.querySelectorAll('.t-line'));
185	    var timers = [];
186	
187	    function play() {
188	      timers.forEach(clearTimeout); timers = [];
189	      lines.forEach(function (l) { l.classList.remove('on'); });
190	      if (REDUCED) { lines.forEach(function (l) { l.classList.add('on'); }); return; }
191	      var t = 200;
192	      lines.forEach(function (l) {
193	        timers.push(setTimeout(function () { l.classList.add('on'); }, t));
194	        // linger on the failing check and its fix line, so the story reads
195	        var idx = Number(l.dataset.t);
196	        t += (idx === 5 || idx === 6) ? 1100 : 480;
197	      });
198	    }
199	
200	    var replay = document.getElementById('term-replay');
201	    if (replay) replay.addEventListener('click', play);
202	
203	    if (!('IntersectionObserver' in window)) { play(); return; }
204	    var seen = false;
205	    var io = new IntersectionObserver(function (entries) {
206	      entries.forEach(function (e) {
207	        if (e.isIntersecting && !seen) { seen = true; play(); io.disconnect(); }
208	      });
209	    }, { threshold: 0.35 });
210	    io.observe(body);
211	  })();
212	
213	  /* ------------------- fleet board: baselining ------------------- */
214	  (function fleetBoard() {
215	    var grid = document.getElementById('repo-grid');
216	    if (!grid) return;
217	    var names = ['payments', 'web-app', 'infra', 'ml-service', 'cli', 'docs-site', 'mobile', 'data-etl'];
218	    var REFS = ['e20584a', (DATA && DATA.canonRef) || '005edd2', '8b31f77'];
219	    var canonRefEl = document.getElementById('canon-ref');
220	    var pulse = document.getElementById('canon-pulse');
221	    var tiles = names.map(function (n) {
222	      var d = el('div', 'repo-tile');
223	      d.appendChild(el('span', 'r-name', n));
224	      d.appendChild(el('span', 'r-ref', REFS[0]));
225	      grid.appendChild(d);
226	      return d;
227	    });
228	
229	    var cur = 1; // canon starts one ref ahead of the fleet
230	    if (canonRefEl) canonRefEl.textContent = REFS[cur];
231	    if (REDUCED) {
232	      tiles.forEach(function (t) {
233	        t.classList.add('fresh');
234	        t.querySelector('.r-ref').textContent = REFS[cur];
235	      });
236	      return;
237	    }
238	    tiles.forEach(function (t) { t.classList.add('stale'); });
239	
240	    function baseline() {
241	      if (pulse) { pulse.classList.remove('go'); void pulse.offsetWidth; pulse.classList.add('go'); }
242	      tiles.forEach(function (t, i) {
243	        setTimeout(function () {
244	          t.classList.remove('stale');
245	          t.classList.add('fresh');
246	          t.querySelector('.r-ref').textContent = REFS[cur];
247	        }, 250 + i * 110);
248	      });
249	      // the canon moves on; the fleet is briefly behind again — that's the loop
250	      setTimeout(function () {
251	        cur = (cur + 1) % REFS.length;
252	        if (canonRefEl) canonRefEl.textContent = REFS[cur];
253	        tiles.forEach(function (t) { t.classList.remove('fresh'); t.classList.add('stale'); });
254	      }, 4600);
255	    }
256	    baseline();
257	    setInterval(baseline, 6400);
258	  })();
259	
260	  /* --------------------- adopt: typewriter ----------------------- */
261	  (function adoptType() {
262	    var target = document.getElementById('type-target');
263	    var result = document.getElementById('adopt-result');
264	    if (!target || !result) return;
265	    var TEXT = 'Adopt Claudinite — follow missingbulb/Claudinite’s bootstrap.md';
266	
267	    if (REDUCED) { target.textContent = TEXT; result.classList.add('on'); return; }
